import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {chromium} from 'playwright';import {load} from 'cheerio';
import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';
const root=path.resolve(process.argv[2]||'artifacts/platform/complianz-installed'),temp=await mkdtemp(path.join(tmpdir(),'complianz-export-'));let browser,server;
try{
 await cp(path.join(root,'project'),temp,{recursive:true});
 if(process.argv.includes('--current-builder'))for(const name of ['consent-export.mjs','component-consent.js'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(temp,'scripts',name));
 const baseline=load(await readFile(path.join(temp,'output/index.html'),'utf8'));assert.ok(baseline('.cmplz-cookiebanner').length,'Capture must preserve installed banner markup');assert.equal(baseline('script[data-cloner-component=consent]').length,0);assert.equal(baseline('.cmplz-cookiebanner').attr('hidden'),'hidden');
 // Owner adds an optional embed to the exported shared home template.
 const file=path.join(temp,'templates/content/home.html');await writeFile(file,(await readFile(file,'utf8'))+'\n\n<div data-cloner-embed id="fixture-map" style="height:240px;width:100%"></div>\n');
 await writeFile(path.join(temp,'consent.json'),JSON.stringify({services:[{id:'map',type:'iframe',targetId:'fixture-map',route:'/',url:'https://embed.test/map',category:'preferences',label:'Fixture map'}]}));
 await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});
 const html=load(await readFile(path.join(temp,'output/index.html'),'utf8'));assert.equal(html('.cmplz-cookiebanner[data-cloner-consent-banner]').length,1);
 server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});const results=[];
 for(const width of [1440,390]){
  const page=await browser.newPage({viewport:{width,height:900}});page.setDefaultTimeout(10000);let frames=0;const blocked=[];
  await page.route('**/*',r=>{const url=new URL(r.request().url());if(url.origin===server.url&&['GET','HEAD'].includes(r.request().method()))return r.continue();if(url.origin==='https://embed.test'&&r.request().method()==='GET'){frames++;return r.fulfill({contentType:'text/html',body:'<p>Local fixture map response</p>'});}blocked.push(r.request().url());return r.abort();});
  await page.goto(server.url+'/',{waitUntil:'networkidle'});const banner=page.locator('[data-cloner-consent-banner]');await banner.waitFor({state:'visible'});await banner.locator('.cmplz-close').focus();await page.keyboard.press('Enter');await banner.waitFor({state:'hidden'});await page.reload({waitUntil:'networkidle'});await banner.waitFor({state:'visible'});assert.equal(frames,0);assert.equal(await page.locator('#fixture-map iframe').count(),0);
  await banner.locator('.cmplz-view-preferences').click();const dialog=page.locator('dialog[data-cloner-consent-dialog]');await dialog.waitFor({state:'visible'});assert.equal(await dialog.getAttribute('data-cloner-consent-presentation'),'complianz');assert.equal(await dialog.locator('[name=preferences]').isChecked(),false);await dialog.locator('.cmplz-category-toggle').click();assert.equal(await dialog.locator('.cmplz-description').isVisible(),true);assert.equal(await dialog.locator('.cmplz-description').innerText(),'Fixture map');await dialog.locator('[name=preferences]').check();assert.equal(await dialog.locator('[name=preferences]').isChecked(),true);await dialog.locator('[name=preferences]').focus();await page.keyboard.press('Space');assert.equal(await dialog.locator('[name=preferences]').isChecked(),false);await page.keyboard.press('Escape');
  await banner.locator('.cmplz-accept').click();await banner.waitFor({state:'hidden'});await page.locator('#fixture-map').scrollIntoViewIfNeeded();await page.waitForFunction(()=>document.querySelector('#fixture-map iframe'));assert.equal(await page.locator('#fixture-map iframe').count(),1);for(let i=0;i<40&&frames===0;i++)await page.waitForTimeout(50);assert.equal(frames,1);
  await page.reload({waitUntil:'networkidle'});assert.equal(await banner.isVisible(),false);assert.equal(await page.locator('#fixture-map iframe').count(),1);
  await page.locator('[data-cloner-consent-reopen]').click();await dialog.waitFor({state:'visible'});assert.equal(await dialog.locator('[name=preferences]').isChecked(),true);assert.equal(await dialog.evaluate(el=>el.getBoundingClientRect().left>=0&&el.getBoundingClientRect().right<=innerWidth),true);
  await dialog.locator('[name=preferences]').uncheck();await dialog.getByRole('button',{name:'Save preferences',exact:true}).click();assert.equal(await page.locator('#fixture-map iframe').count(),0);await page.locator('[data-cloner-consent-reopen]').click();await dialog.locator('[name=preferences]').check();await dialog.getByRole('button',{name:'Save preferences',exact:true}).click();assert.equal(await page.locator('#fixture-map iframe').count(),1);await page.locator('[data-cloner-consent-reopen]').click();
  await page.screenshot({path:path.join(root,'consent-export-'+width+'.png')});await dialog.getByRole('button',{name:'Reject optional services',exact:true}).click();assert.equal(await page.locator('#fixture-map iframe').count(),0);assert.deepEqual(blocked,[]);
  results.push({width,defaultDenied:true,installedBannerControls:true,sourceCategoryControls:true,selectiveSave:true,keyboardDismiss:true,persisted:true,reopened:true,revoked:true});await page.close();
 }
 await writeFile(path.join(root,'consent-export-check.json'),JSON.stringify({results,candidateBuilder:process.argv.includes('--current-builder'),embedRequestsInterceptedLocally:true,sourceTrackingRevived:false,sourcePreferenceVisualParity:false},null,2));console.log(JSON.stringify(results));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
